export function Assignee({
  name = "{{name}}",
  initials = "{{initials}}",
  role = "{{role}}",
  status = "{{status}}",
  accent = "{{accent}}",
  showRole = {{showRole}},
}) {
  const info = {
    assigned: { text: "Assigned to this item", color: "#1a7a4c" },
    unassigned: { text: "Unassigned — needs an owner", color: "#24143099" },
    pending: { text: "Invite pending", color: "#8a5d00" },
  }[status] ?? { text: "Assigned to this item", color: "#1a7a4c" };
  const unassigned = status === "unassigned";
  return (
    <div style={{ display: "flex", gap: 12, alignItems: "flex-start", fontFamily: "system-ui, sans-serif",
      fontSize: 14, color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, maxWidth: 340, boxSizing: "border-box" }}>
      <span style={{ flex: "none", width: 40, height: 40, borderRadius: "50%",
        background: unassigned ? "transparent" : accent, border: unassigned ? "2px dashed #24143066" : "2px solid transparent",
        color: unassigned ? "#24143066" : "#241430", display: "flex", alignItems: "center", justifyContent: "center",
        fontWeight: 700, fontSize: 13 }}>{initials}</span>
      <div>
        <p style={{ margin: 0, fontWeight: 600 }}>{name}</p>
        {showRole && <p style={{ margin: "2px 0 0", color: "#241430b3", fontSize: 13 }}>{role}</p>}
        <p style={{ display: "flex", alignItems: "center", gap: 6, margin: "8px 0 0", fontSize: 13, fontWeight: 600, color: info.color }}>
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
            {status === "assigned" && <path d="M3 8.5l3 3 7-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />}
            {status === "unassigned" && <><circle cx="8" cy="8" r="6" stroke="currentColor" strokeWidth="1.6" /><path d="M4 4l8 8" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" /></>}
            {status === "pending" && <><circle cx="8" cy="8" r="6" stroke="currentColor" strokeWidth="1.6" /><path d="M8 4.5V8l3 1.6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" /></>}
          </svg>
          {info.text}
        </p>
      </div>
    </div>
  );
}
